validator:
function validate(input) {
  const [{ products = [] }] = input;
  const ids = new Set();
  for (const [id] of products) {
    if (id === null) return 'Every product needs a product_id.';
    if (ids.has(id)) return `product_id ${id} appears twice.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const digits = n => Array.from({ length: n }, () => Math.floor(rand() * 10)).join('');
  const words = ['This', 'is', 'a', 'product', 'with', 'serial', 'Check', 'out', 'No', 'number', 'here', 'model', 'v2', 'in', 'stock'];
  const serial = () => {
    const r = rand();
    if (r < 0.45) return `SN${digits(4)}-${digits(4)}`;
    if (r < 0.55) return `${pick(['sn', 'Sn', 'sN'])}${digits(4)}-${digits(4)}`;
    if (r < 0.75) return `SN${digits(pick([3, 4, 5]))}${pick(['-', '-', '_', '', ' - ', '--'])}${digits(pick([3, 4, 5]))}`;
    return `${pick(['X', '9', '_', '(', '#', ''])}SN${digits(4)}-${digits(4)}${pick(['X', '7', '_', ')', '.', ','])}`;
  };
  const description = () => {
    const parts = [];
    for (let i = 0, n = 1 + Math.floor(rand() * 5); i < n; i++) parts.push(rand() < 0.3 ? serial() : pick(words));
    return parts.join(rand() < 0.9 ? ' ' : '');
  };
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const ids = Array.from({ length: rows }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const products = ids.map(id => [id, `Widget ${pick(['A', 'B', 'C', 'D', 'E'])}`, description()]);
  return [{ products }];
}
